var list = [4, 0, 5, 0, 0, 6];
var pos = 0;
for (var i = 0; i < list.length; i++) {
  if (list[i] !== 0) {
    var temp = list[pos];
    list[pos] = list[i];
    list[i] = temp;
    pos++;
  }
}
console.log(list);
